def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5

def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_dedupe_sessions_keeps_last_record_for_duplicate_id():
    events = [
        {"id": "x", "day": 1, "converted": True},
        {"id": "y", "day": 2, "converted": False},
        {"id": "x", "day": 3, "converted": False},
    ]
    assert dedupe_sessions(events) == [
        {"id": "y", "day": 2, "converted": False},
        {"id": "x", "day": 3, "converted": False},
    ]
